// voiceKnowledge.js — grounding + links for the JARVIS voice panel.
//
// Three jobs, all derived from portfolio.js so they never drift from the site:
//   1. retrieveContext(question) — semantic retrieval over portfolio chunks
//      (same embedTexts Cloud Function as the AI Brain), keyword fallback.
//   2. buildAnswerLinks(...)     — tappable next steps under an answer
//      (project pages, CV, contact, GitHub) instead of auto-navigating.
//   3. correctTranscript / recognitionLang — speech-to-text fix-ups for the
//      names browsers reliably mishear ("cams lens", "lakshman", "IIT daily").

import {
  projects,
  experience,
  degrees,
  skills,
  greeting,
  socialMediaLinks,
} from "../../portfolio";

const EMBED_URL =
  "https://us-central1-portfolio-142b7.cloudfunctions.net/embedTexts";
const CACHE_KEY = "jarvis.voice.embeds.v1";
const QUERY_TIMEOUT_MS = 1200;
const TOP_K = 4;

// Strip decoration so labels and chunks read cleanly ("CAMS Lens 🔍 — …").
const clean = (s = "") =>
  String(s)
    .replace(/[\u{1F000}-\u{1FFFF}\u{2600}-\u{27BF}\u{FE0F}]/gu, "")
    .replace(/^[\s⚡•-]+/, "")
    .replace(/\s+/g, " ")
    .trim();

const shortName = (name) =>
  clean(name)
    .split(/\s+[—–-]\s+|\s*\(/)[0]
    .trim();

// ---------------------------------------------------------------------------
// Project index
// ---------------------------------------------------------------------------

const EXTRA_ALIASES = {
  "cams-lens": ["camslens", "cams lens"],
  camscode: ["cams code"],
  "intelligent-document-processing": ["idp", "document processing"],
  "research-intelligence-agent": ["research agent", "research assistant"],
  "sebi-debarred-pan-extraction": ["pan extraction", "debarred"],
  "ai-email-automation": ["email automation"],
  "ipo-monitoring-system": ["ipo monitoring", "ipo monitor"],
};

export const PROJECT_INDEX = (projects?.data || [])
  .filter((p) => p.slug && p.name)
  .map((p) => {
    const label = shortName(p.name);
    const aliases = [label.toLowerCase(), ...(EXTRA_ALIASES[p.slug] || [])];
    return { slug: p.slug, label, aliases, project: p };
  });

const escapeRe = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
const mentions = (text, alias) =>
  new RegExp(`\\b${escapeRe(alias)}\\b`, "i").test(text);

// ---------------------------------------------------------------------------
// 1. Retrieval
// ---------------------------------------------------------------------------

const buildChunks = () => {
  const chunks = [];

  PROJECT_INDEX.forEach(({ label, project: p }) => {
    const tech = (p.languages || []).map((l) => l.name).join(", ");
    chunks.push(
      `Project — ${label}: ${clean(p.description)}${
        tech ? ` Tech: ${tech}.` : ""
      }`
    );
  });

  (experience?.sections || []).forEach((section) =>
    (section.experiences || []).forEach((e) =>
      chunks.push(
        `${clean(section.title)} — ${e.title} at ${e.company} (${e.duration}, ${
          e.location || ""
        }): ${clean(e.description)}`
      )
    )
  );

  (degrees?.degrees || []).forEach((d) =>
    chunks.push(
      `Education — ${clean(d.title)}, ${d.subtitle} (${d.duration}). ${(
        d.descriptions || []
      )
        .map(clean)
        .join(" ")}`
    )
  );

  (skills?.data || []).forEach((s) =>
    chunks.push(
      `Skills — ${clean(s.title)}: ${(s.skills || []).map(clean).join(" ")}${
        s.softwareSkills?.length
          ? ` Tools: ${s.softwareSkills
              .map((t) => t.skillName || t.name)
              .filter(Boolean)
              .join(", ")}.`
          : ""
      }`
    )
  );

  return chunks.filter((c) => c.length > 20);
};

let CHUNKS = null;
const getChunks = () => (CHUNKS = CHUNKS || buildChunks());

// djb2 — cache key for a chunk's vector, so an edited chunk re-embeds.
const hash = (s) => {
  let h = 5381;
  for (let i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) | 0;
  return (h >>> 0).toString(36);
};

const readCache = () => {
  try {
    return JSON.parse(localStorage.getItem(CACHE_KEY) || "{}");
  } catch (e) {
    return {};
  }
};

const writeCache = (cache) => {
  try {
    localStorage.setItem(CACHE_KEY, JSON.stringify(cache));
  } catch (e) {
    /* quota or private mode — vectors just won't persist */
  }
};

const embed = async (texts, signal) => {
  const res = await fetch(EMBED_URL, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ texts }),
    signal,
  });
  if (!res.ok) throw new Error(`embedTexts ${res.status}`);
  const data = await res.json();
  if (!Array.isArray(data?.vectors)) throw new Error("embedTexts: no vectors");
  return data.vectors;
};

let chunkVectors = null; // aligned with getChunks(), or null until warmed
let warming = null;

// Embed every chunk once (cached across visits). Called when the panel opens
// so the first question doesn't pay for it.
export const warmKnowledge = () => {
  if (chunkVectors || warming) return warming;
  const chunks = getChunks();
  const cache = readCache();
  const missing = chunks.filter((c) => !cache[hash(c)]);

  warming = (async () => {
    try {
      for (let i = 0; i < missing.length; i += 100) {
        const batch = missing.slice(i, i + 100);
        // eslint-disable-next-line no-await-in-loop
        const vectors = await embed(batch);
        batch.forEach((c, j) => {
          cache[hash(c)] = vectors[j].map((v) => Math.round(v * 1e5) / 1e5);
        });
      }
      if (missing.length) writeCache(cache);
      chunkVectors = chunks.map((c) => cache[hash(c)]);
    } catch (e) {
      console.warn("🧭 Voice knowledge: semantic index unavailable", e.message);
    } finally {
      warming = null;
    }
  })();
  return warming;
};

const cosine = (a, b) => {
  let dot = 0;
  let na = 0;
  let nb = 0;
  for (let i = 0; i < a.length; i++) {
    dot += a[i] * b[i];
    na += a[i] * a[i];
    nb += b[i] * b[i];
  }
  return dot / (Math.sqrt(na * nb) || 1);
};

const STOP = new Set(
  "a an the is are was were what who how when where why which do does did he his him laxman tell me about of in on for to and or with can you your i it this that".split(
    " "
  )
);
const tokens = (s) =>
  s
    .toLowerCase()
    .split(/[^a-z0-9+#.]+/)
    .filter((t) => t.length > 1 && !STOP.has(t));

const keywordTop = (question, chunks) => {
  const q = tokens(question);
  if (!q.length) return [];
  return chunks
    .map((c) => {
      const lc = c.toLowerCase();
      return { c, score: q.reduce((n, t) => n + (lc.includes(t) ? 1 : 0), 0) };
    })
    .filter((x) => x.score > 0)
    .sort((a, b) => b.score - a.score)
    .slice(0, TOP_K)
    .map((x) => x.c);
};

/**
 * The few portfolio facts most relevant to `question`, as prompt-ready text.
 * Never throws and never waits more than ~1.2s: semantic when the index is
 * warm, keyword overlap otherwise, empty string for small talk.
 */
export const retrieveContext = async (question) => {
  const chunks = getChunks();
  if (!question || tokens(question).length === 0) return "";

  let picked = [];
  if (chunkVectors) {
    const ctrl =
      typeof AbortController !== "undefined" ? new AbortController() : null;
    const timer = setTimeout(() => ctrl && ctrl.abort(), QUERY_TIMEOUT_MS);
    try {
      const [qv] = await embed([question], ctrl?.signal);
      picked = chunks
        .map((c, i) => ({
          c,
          s: chunkVectors[i] ? cosine(qv, chunkVectors[i]) : -1,
        }))
        .sort((a, b) => b.s - a.s)
        .slice(0, TOP_K)
        .filter((x) => x.s > 0.55)
        .map((x) => x.c);
    } catch (e) {
      /* timeout / offline — fall through to keywords */
    } finally {
      clearTimeout(timer);
    }
  } else {
    warmKnowledge();
  }

  if (!picked.length) picked = keywordTop(question, chunks);
  return picked.map((c) => `- ${c}`).join("\n");
};

// ---------------------------------------------------------------------------
// 2. Answer links
// ---------------------------------------------------------------------------

const ACTION_LINKS = {
  NAVIGATE_PROJECTS: { label: "See projects", href: "/projects" },
  HIGHLIGHT_PROJECTS: { label: "See projects", href: "/projects" },
  NAVIGATE_EXPERIENCE: { label: "See experience", href: "/experience" },
  HIGHLIGHT_EXPERIENCE: { label: "See experience", href: "/experience" },
  NAVIGATE_EDUCATION: { label: "See education", href: "/education" },
  HIGHLIGHT_EDUCATION: { label: "See education", href: "/education" },
  NAVIGATE_CONTACT: { label: "Contact Laxman", href: "/contact" },
  HIGHLIGHT_CONTACT: { label: "Contact Laxman", href: "/contact" },
  NAVIGATE_GITHUB: {
    label: "GitHub",
    href: socialMediaLinks?.github,
    external: true,
  },
};

/**
 * Up to three next steps for an answer. The model's suggested page action is
 * offered here as a link rather than executed, so visitors are never toured
 * through pages they didn't ask to see.
 */
export const buildAnswerLinks = ({ question = "", answer = "", action }) => {
  const links = [];
  const add = (l) => {
    if (l?.href && !links.some((x) => x.href === l.href)) links.push(l);
  };

  // Projects named in the answer (or asked about) — most specific first.
  const both = `${question} ${answer}`;
  PROJECT_INDEX.forEach(({ slug, label, aliases }) => {
    if (aliases.some((a) => mentions(both, a))) {
      add({ label: `Open ${label}`, href: `/projects/${slug}` });
    }
  });

  if (
    /\b(hire|hiring|recruit|contact|reach|email|get in touch)\b/i.test(question)
  ) {
    add({ label: "Contact Laxman", href: "/contact" });
  }
  if (/\b(resume|cv|curriculum)\b/i.test(both)) {
    add({ label: "View CV", href: greeting?.resumeLink, external: true });
  }

  const projMatch = /^HIGHLIGHT_PROJECT_(\d+)$/.exec(action || "");
  if (projMatch) {
    const p = PROJECT_INDEX[Number(projMatch[1]) - 1];
    if (p) add({ label: `Open ${p.label}`, href: `/projects/${p.slug}` });
  }
  if (action && ACTION_LINKS[action]) add(ACTION_LINKS[action]);

  if (/\bgithub\b/i.test(both)) add(ACTION_LINKS.NAVIGATE_GITHUB);

  return links.slice(0, 3);
};

// ---------------------------------------------------------------------------
// 3. Speech-to-text fix-ups
// ---------------------------------------------------------------------------

const CORRECTIONS = [
  [/\b(?:lakshman|laxmun|lax man|lucks man|laksman|luxman)\b/gi, "Laxman"],
  [/\b(?:cams?|kams|calms|cam's)\s*lens\b/gi, "CAMS Lens"],
  [/\b(?:cams?|kams|calms|cam's)\s*code\b/gi, "CAMSCode"],
  [/\bops\s*pilot\b/gi, "OpsPilot"],
  [/\broom\s*flow\b/gi, "RoomFlow"],
  [/\bnext\s*gen\s*gaming\b/gi, "NexGenGaming"],
  [
    /\b(?:i\s*i\s*t|eye eye tea|iit)\s*(?:delhi|daily|deli|dilli)\b/gi,
    "IIT Delhi",
  ],
  [/\bthink\s*360\b/gi, "Think360"],
];

export const correctTranscript = (text = "") =>
  CORRECTIONS.reduce((t, [re, to]) => t.replace(re, to), text);

// The visitor's own English variant hears their accent better (en-IN for most
// Indian visitors); anything non-English falls back to en-US, which the
// answers are written in.
export const recognitionLang = () => {
  const lang =
    (typeof navigator !== "undefined" &&
      (navigator.languages?.find((l) => /^en\b/i.test(l)) ||
        navigator.language)) ||
    "";
  return /^en-[A-Z]{2}$/i.test(lang) ? lang : "en-US";
};
